/// <summary>
/// AVA/WEN/2025/01/24  AVA_013036_ReverseJournal
/// </summary>
class AVACreateReversalJourUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField dlgUseExistingDates, dlgReversalDate, dlgReversalReason;
    AVACreateReversalJourContract contract;

}

Method.Source:
public void postBuild()
{
    super();
    contract = this.dataContractObject();

    dlgUseExistingDates = this.bindInfo().getDialogField(contract, methodStr(AVACreateReversalJourContract, parmUseExistingDates));

    dlgReversalDate = this.bindInfo().getDialogField(contract, methodStr(AVACreateReversalJourContract, parmReversalDate));
    dlgReversalReason = this.bindInfo().getDialogField(contract, methodStr(AVACreateReversalJourContract, parmreversalReason));

    dlgUseExistingDates.registerOverrideMethod(methodstr(FormCheckBoxControl, modified), methodStr(AVACreateReversalJourUIBuilder, modifiedUseExistingDates), this);

}

/// <summary>
/// AVA/WEN/2025/01/24  AVA_013036_ReverseJournal
/// </summary>
/// <param name = "_dialogCheckBox">FormCheckBoxControl</param>
/// <returns>booolean</returns>
public boolean modifiedUseExistingDates(FormCheckBoxControl _dialogCheckBox)
{
    boolean useExistingDates;

    useExistingDates = _dialogCheckBox.checked();

    if (useExistingDates)
    {
        dlgReversalDate.allowEdit(false);
        dlgReversalDate.value(dateNull());
    }
    else
    {
        dlgReversalDate.allowEdit(true);
        dlgReversalDate.fieldControl().mandatory(true);
    }

    return true;
}
